/** Injected fault classes (R7, architecture 10.2), each offered as an alternative and counted only once acknowledged (dispatched and settled). timeout_before_effect: the request is lost before the provider acts; timeout_after_effect: the provider commits and the reply is lost; partial_effect: a multi-part operation commits a strict prefix, then its reply is lost; duplicate_delivery: a request reaches the provider twice (a transport retry); ack_loss: a message acknowledgment is lost and the broker redelivers the message; crash_restart: an actor loses its in-memory state (locals, open transaction, held messages, which are redelivered) and restarts, durable effects kept. Redelivery is a consequence of ack_loss and crash_restart, not a class of its own. */
export const FaultClassValues = ["timeout_before_effect", "timeout_after_effect", "partial_effect", "duplicate_delivery", "ack_loss", "crash_restart"] as const;
export type FaultClass = (typeof FaultClassValues)[number];
export function encodeFaultClass(v: FaultClass): Json {
  return v;
}
export function decodeFaultClass(j: Json, path: string): FaultClass {
  return decEnum(j, path, FaultClassValues, "FaultClass");
}

/** Where data alternatives come from. recorded: a finite set of persisted responses or inputs, replayed without calling anything; sampled: fresh draws from a model or generator, persisted when drawn. Neither enumerates the source's output space; sampled alternatives are a separate experiment with its own budget and claims. */
export const ChoiceSourceValues = ["recorded", "sampled"] as const;
export type ChoiceSource = (typeof ChoiceSourceValues)[number];
export function encodeChoiceSource(v: ChoiceSource): Json {
  return v;
}
export function decodeChoiceSource(j: Json, path: string): ChoiceSource {
  return decEnum(j, path, ChoiceSourceValues, "ChoiceSource");
}

/** What an alternative perturbs besides schedule order (R7). fault: an injected fault of class on the operation whose ordinary alternative is `of`; timer: expiry of `timer` at virtual deadline `deadline` (virtual time advances only by selected expiries); data: one alternative value of `slot` (a recorded model response, retrieved document or tool output) labelled `label`. */
export type AlternativeKind = { kind: "fault"; class: FaultClass; of: string } | { kind: "timer"; timer: string; deadline: bigint } | { kind: "data"; slot: string; label: string; source: ChoiceSource };
export function encodeAlternativeKind(v: AlternativeKind): Json {
  const m = new Map<string, Json>();
  m.set("kind", v.kind);
  switch (v.kind) {
    case "fault": {
      m.set("class", encodeFaultClass(v.class));
      m.set("of", encString(v.of));
      break;
    }
    case "timer": {
      m.set("timer", encString(v.timer));
      m.set("deadline", encBig(v.deadline));
      break;
    }
    case "data": {
      m.set("slot", encString(v.slot));
      m.set("label", encString(v.label));
      m.set("source", encodeChoiceSource(v.source));
      break;
    }
  }
  return new JObj(m);
}
export function decodeAlternativeKind(j: Json, path: string): AlternativeKind {
  const m = obj(j, path);
  const kind = req(m, "kind", path, decString);
  switch (kind) {
    case "fault":
      onlyFields(m, ["class", "of", "kind"], path);
      return { kind: "fault", class: req(m, "class", path, decodeFaultClass), of: req(m, "of", path, decId) };
    case "timer":
      onlyFields(m, ["timer", "deadline", "kind"], path);
      return { kind: "timer", timer: req(m, "timer", path, decString), deadline: req(m, "deadline", path, decU64) };
    case "data":
      onlyFields(m, ["slot", "label", "source", "kind"], path);
      return { kind: "data", slot: req(m, "slot", path, decString), label: req(m, "label", path, decString), source: req(m, "source", path, decodeChoiceSource) };
    default:
      throw new DecodeError("unknown_variant", path, `unknown AlternativeKind ${kind}`);
  }
}

/** One eligible operation. id derives from logical lineage and occurrence (stable across re-execution); actor is the sequential process performing it. footprints over-approximate what it may touch: an empty list means unknown scope in every namespace. enabled_by (R6): alternatives already executed in this trial that made it eligible (spawn, send); absent means unknown, and reductions that need it fall back to full exploration. kind (R7): absent for an ordinary scheduling alternative; otherwise the fault, timer expiry or data value it selects. */
