export function encodeAlternative(v: Alternative): Json {
  const m = new Map<string, Json>();
  m.set("id", encString(v.id));
  m.set("op", encodeOperationRef(v.op));
  if (v.actor !== undefined) m.set("actor", encString(v.actor));
  m.set("footprints", v.footprints.map((e) => encodeFootprint(e)));
  if (v.enabled_by !== undefined) m.set("enabled_by", v.enabled_by.map((e) => encString(e)));
  if (v.kind !== undefined) m.set("kind", encodeAlternativeKind(v.kind));
  return new JObj(m);
}
export function decodeAlternative(j: Json, path: string): Alternative {
  const m = obj(j, path);
  onlyFields(m, ["id", "op", "actor", "footprints", "enabled_by", "kind"], path);
  return { id: req(m, "id", path, decId), op: req(m, "op", path, decodeOperationRef), actor: opt(m, "actor", path, decId), footprints: req(m, "footprints", path, decList(decodeFootprint)), enabled_by: opt(m, "enabled_by", path, decList(decId)), kind: opt(m, "kind", path, decodeAlternativeKind) };
}

/** A before-effect choice offered by an adapter, with its eligible alternatives and exclusions. */
